'use strict';
function posProfitMarkup(result){
 const title='<h3>Rentabilidad en tiempo real</h3>';
 if(result.status==='invalid')return title+'<p class="muted">Revisa las cantidades, precios y descuentos para calcular la utilidad.</p>';
 if(result.status==='missing-cost')return title+'<p class="muted">Falta el costo de una pieza. No se puede calcular su utilidad.</p>';
 if(result.status==='empty')return '';
 return title+'<dl><div><dt>Costo total</dt><dd>'+money(result.cost)+'</dd></div><div><dt>Venta al cliente · sin impuestos</dt><dd>'+money(result.sale)+'</dd></div><div class="pos-profit-result"><dt>Utilidad bruta estimada</dt><dd>'+(result.profit===null?'Por definir':money(result.profit))+'</dd></div><div><dt>Margen sobre la venta</dt><dd>'+(result.margin===null?'Fijar precio de venta':result.margin.toFixed(1)+' %')+'</dd></div></dl>'+(result.loss?'<p class="pos-profit-warning">Venta por debajo del costo. Esta venta genera pérdida bruta.</p>':'')+(result.zeroCost?'<p class="muted">Hay piezas con costo registrado en cero. Revisa su costo antes de vender.</p>':'')+'<small>No incluye gastos operativos. Se confirma al registrar la venta; en separes, al entregar.</small>';
}
function paintPosProfit(holder,result){holder.hidden=result.status==='empty';holder.classList.toggle('is-loss',Boolean(result.loss));holder.innerHTML=posProfitMarkup(result);}
function currentProfitItems(){return appState.cart.map((row,i)=>({...row,qty:document.querySelector('[data-cart-qty="'+i+'"]')?.value??row.qty,unitPrice:document.querySelector('[data-unit-price="'+i+'"]')?.value??row.unitPrice,discount:document.querySelector('[data-discount="'+i+'"]')?.value??row.discount}));}
function refreshPosProfit(){if(!PosProfitPolicy.canView(appState.user))return;const holder=document.querySelector('#pos-cart-profit');if(holder)paintPosProfit(holder,PosProfitPolicy.calculate(currentProfitItems(),data().products));}
const profitCartView=cartView;
cartView=function(){const html=profitCartView();if(!PosProfitPolicy.canView(appState.user)||!appState.cart.length)return html;const host=document.createElement('div');host.innerHTML=html;host.querySelector('.cart-summary .grand').insertAdjacentHTML('beforebegin','<section class="pos-profit" id="pos-cart-profit" aria-label="Rentabilidad de la venta">'+posProfitMarkup(PosProfitPolicy.calculate(appState.cart,data().products))+'</section>');const result=PosProfitPolicy.calculate(appState.cart,data().products);host.querySelector('#pos-cart-profit').classList.toggle('is-loss',Boolean(result.loss));return host.innerHTML;};
const profitRefreshTotals=refreshCartTotals;
refreshCartTotals=function(){profitRefreshTotals();refreshPosProfit();};
function refreshQuoteProfit(){const form=document.querySelector('#parity-quote-form'),holder=form?.querySelector('.pos-profit');if(!holder||!PosProfitPolicy.canView(appState.user))return;const row=appState.cart[Number(form.dataset.index)],p=data().products.find(p=>p.id===row.productId),values=Object.fromEntries(new FormData(form)),item=PosProfitPolicy.quote(row,p,values);const result=PosProfitPolicy.calculate([item],data().products);paintPosProfit(holder,result);const preview=form.querySelector('#quote-preview');if(preview)preview.textContent=result.status==='invalid'?'Revisa la cantidad y el precio de la línea.':'Peso de referencia: '+grams(p.weight)+' · Total de línea: '+money(Math.round(item.qty*item.unitPrice)-(item.discount||0));}
const profitModal=extraUI.modal;
extraUI.modal=function(){profitModal?.();const form=document.querySelector('#parity-quote-form');if(!form)return;form.querySelector('#audit-profit-preview')?.remove();if(!PosProfitPolicy.canView(appState.user))return;const holder=document.createElement('section');holder.className='pos-profit';holder.setAttribute('aria-label','Rentabilidad de la pieza');form.querySelector('button[type="submit"]').before(holder);refreshQuoteProfit();};
document.addEventListener('input',e=>{if(e.target.matches('[data-cart-qty],[data-unit-price],[data-discount]'))refreshPosProfit();if(e.target.closest('#parity-quote-form'))refreshQuoteProfit();});
